class Exercise {
    // 값이 바뀌는 줄을 실행 결과와 비교해요.
    static int run(String text) {
        // 단어마다 누적 횟수를 저장해요.
        var count=new java.util.HashMap<String,Integer>();
        for(String word:text.split(",")) count.put(word,1);
        // 처음 단어가 몇 번 나왔는지 확인해요.
        return count.get(text.split(",")[0]);
    }
}
